/* From Uiverse.io by NotReal22 - Tags: card, stylish */
.__UIV_SCOPE__ .card-2 {
  position: relative;
  width: 300px;
  height: 400px;
  background-image: linear-gradient(to top,rgb(117, 117, 197),#67be96);
  border-radius: 30px;
  border: 2px solid white;
  overflow: hidden;
}

.__UIV_SCOPE__ .h1-circle {
  position: absolute;
  right: 70px;
  border-radius: 50%;
  width: 400px;
  height: 400px;
  background-image: radial-gradient(circle at center, #8798c5, #494fa1);
  opacity: .8;
}

.__UIV_SCOPE__ .card-2:hover .h1-circle,
.__UIV_SCOPE__ .h1-circle:hover {
  animation: moving-weel 1s linear;
  animation-fill-mode: forwards;
}

.__UIV_SCOPE__ .h1-circle:not(:hover) {
  animation: moving-weel-2 1s linear;
  animation-fill-mode: backwards;
}

@keyframes moving-weel-2 {
  0% {
    rotate: 160deg;
    right: -170px;
  }

  50% {
    right: 20px;
    rotate: 75deg;
  }

  100% {
    rotate: 0deg;
  }
}

@keyframes moving-weel {
  0% {
    rotate: 0deg;
  }

  50% {
    right: 20px;
    rotate: 90deg;
  }

  100% {
    rotate: 180deg;
    right: -170px;
  }
}

.__UIV_SCOPE__ .h1-circle ul li {
  list-style: none;
  color: white;
  font-size: 20px;
  margin: 20px;
}

.__UIV_SCOPE__ #h1-circle-ul-1 {
  display: flex;
  flex: 1;
  flex-direction: column;
  position: absolute;
  top: 100px;
  left: 200px;
  transition: 500ms ease-in;
}

.__UIV_SCOPE__ #h1-circle-ul-2 {
  opacity: 0;
  flex: 1;
  flex-direction: column;
  position: absolute;
  top: 100px;
  left: 200px;
  transition: 1s ease-in;
}

.__UIV_SCOPE__ #h1-circle-ul-2 li {
  transform: rotate(180deg);
  font-size: 20px;
  margin: 30px;
}

.__UIV_SCOPE__ #card-2-h1 {
  position: absolute;
  left: 60px;
  top: 10px;
  color: transparent;
  font-size: 40px;
  font-family: 'Lucida Sans', 'Lucida Sans Regular', 'Lucida Grande', 'Lucida Sans Unicode', Geneva, Verdana, sans-serif;
  z-index: 700;
  background: linear-gradient(to bottom right, transparent, white 90%),rgb(117, 190, 117);
  -webkit-background-clip: text;
  background-clip: text;
  text-transform: uppercase;
  transition: 1s ease-in;
}

.__UIV_SCOPE__ .card-2:hover #h1-circle-ul-2 {
  opacity: 1;
  transition: 1s ease-in;
}

.__UIV_SCOPE__ .card-2:hover #h1-circle-ul-1 {
  opacity: 0;
  transition: 500ms ease-in;
}
